const { catalogueReadPredicate } = require("./catalogue-scope.cjs");
/**
 * Build the SQL Server equivalent of the branch predicates generated for the
 * Supabase synchronization RPCs. Registry names are trusted build artifacts;
 * branch and cutoff values are always bound parameters.
 */
function columnNames(table) {
  return new Set((table?.columns ?? []).map((column) => column.sqlServerColumn));
}

function branchPredicate(registry, table, alias = "source", seen = new Set()) {
  if (!table || seen.has(table.sqlServerTable)) return null;
  const nextSeen = new Set(seen).add(table.sqlServerTable);
  const names = columnNames(table);
  if (names.has("store_id")) return `${alias}.[store_id]=@branch`;
  if (names.has("branch_id")) return `${alias}.[branch_id]=@branch`;
  // Catalogue rows are either shared (no owner) or owned by exactly one
  // branch. Treat shared products as visible everywhere, while preventing a
  // terminal from reading or uploading another branch's owned catalogue.
  if (names.has("owner_store_id"))
    return `(NULLIF(${alias}.[owner_store_id],N'') IS NULL OR ${alias}.[owner_store_id]=@branch)`;
  if (names.has("from_store_id") && names.has("to_store_id"))
    return `(${alias}.[from_store_id]=@branch OR ${alias}.[to_store_id]=@branch)`;
  for (const column of table.columns ?? []) {
    if (!column.foreignKey || !column.foreignKeyTarget) continue;
    const parent = (registry.tables ?? []).find((candidate) =>
      candidate.cloudTable === column.foreignKeyTarget.table ||
      candidate.sqlServerTable === column.foreignKeyTarget.table);
    if (!parent) continue;
    const parentFilter = branchPredicate(registry, parent, "parent", nextSeen);
    if (!parentFilter) continue;
    const parentColumn = parent.columns.find((candidate) => candidate.cloudColumn === column.foreignKeyTarget.column);
    const parentKey = parentColumn?.sqlServerColumn ?? column.foreignKeyTarget.column;
    const linked = `EXISTS (SELECT 1 FROM dbo.[${parent.sqlServerTable}] parent WHERE parent.[${parentKey}]=${alias}.[${column.sqlServerColumn}] AND ${parentFilter})`;
    // Match the cloud contract: a promotion without a free-item product is
    // shared. A linked promotion still follows that product's branch scope.
    return table.cloudTable === "promotions" && column.cloudColumn === "foc_product_id"
      ? `(${alias}.[${column.sqlServerColumn}] IS NULL OR ${linked})` : linked;
  }
  return null;
}

/**
 * Renderer reads may recover purchase orders written by old desktop builds
 * before store_id was projected. The local database is paired to one branch,
 * so an unowned receiving row can be shown to that till and claimed on its
 * next save. A non-empty branch mismatch remains hidden. This relaxed rule is
 * deliberately read-only; writes use branchPredicate(). The sync reader also
 * uses it so PushWorker can stamp an unowned legacy order before uploading it.
 */
function rendererReadBranchPredicate(registry, table, alias = "source", seen = new Set()) {
  if (!table || seen.has(table.sqlServerTable)) return null;
  const nextSeen = new Set(seen).add(table.sqlServerTable);
  const names = columnNames(table);
  if (names.has("store_id")) {
    const owned = `${alias}.[store_id]=@branch`;
    return table.cloudTable === "purchase_orders"
      ? `(${owned} OR NULLIF(${alias}.[store_id],N'') IS NULL)`
      : owned;
  }
  if (names.has("branch_id")) return `${alias}.[branch_id]=@branch`;
  if (table.cloudTable === "products" && names.has("owner_store_id"))
    return catalogueReadPredicate(registry, alias);
  if (names.has("owner_store_id"))
    return `(NULLIF(${alias}.[owner_store_id],N'') IS NULL OR ${alias}.[owner_store_id]=@branch)`;
  if (names.has("from_store_id") && names.has("to_store_id"))
    return `(${alias}.[from_store_id]=@branch OR ${alias}.[to_store_id]=@branch)`;
  for (const column of table.columns ?? []) {
    if (!column.foreignKey || !column.foreignKeyTarget) continue;
    const parent = (registry.tables ?? []).find((candidate) =>
      candidate.cloudTable === column.foreignKeyTarget.table ||
      candidate.sqlServerTable === column.foreignKeyTarget.table);
    if (!parent) continue;
    const parentFilter = rendererReadBranchPredicate(registry, parent, "parent", nextSeen);
    if (!parentFilter) continue;
    const parentColumn = parent.columns.find(
      (candidate) => candidate.cloudColumn === column.foreignKeyTarget.column,
    );
    const parentKey = parentColumn?.sqlServerColumn ?? column.foreignKeyTarget.column;
    const linked = `EXISTS (SELECT 1 FROM dbo.[${parent.sqlServerTable}] parent WHERE parent.[${parentKey}]=${alias}.[${column.sqlServerColumn}] AND ${parentFilter})`;
    return table.cloudTable === "promotions" && column.cloudColumn === "foc_product_id"
      ? `(${alias}.[${column.sqlServerColumn}] IS NULL OR ${linked})` : linked;
  }
  return null;
}

function dateColumn(table) {
  const names = columnNames(table);
  return ["created_at", "paid_at", "occurred_at", "updated_at"].find((name) => names.has(name)) ?? null;
}

// Download verification must compare the same catalogue as the cloud reader.
// Keep the upload/write predicate (and legacy receiving read exception) intact.
function comparisonBranchPredicate(registry, table, alias = "source") {
  if (table?.cloudTable === "products" && columnNames(table).has("owner_store_id"))
    return catalogueReadPredicate(registry, alias);
  const link = table?.cloudTable === "product_barcodes" ? "product_id"
    : table?.cloudTable === "promotions" ? "foc_product_id" : null;
  if (!link) return branchPredicate(registry, table, alias);
  const product = registry.tables.find(candidate => candidate.cloudTable === "products");
  if (!product || !columnNames(table).has(link)) return "1=0";
  const related = `EXISTS (SELECT 1 FROM dbo.[${product.sqlServerTable}] catalogue_product WHERE catalogue_product.[id]=${alias}.[${link}] AND ${catalogueReadPredicate(registry, "catalogue_product")})`;
  return link === "foc_product_id" ? `(${alias}.[${link}] IS NULL OR ${related})` : related;
}

function settingsScopePredicate(table, alias = "source") {
  if (!["settings_overrides", "settings_scoped"].includes(table?.cloudTable)) return null;
  return `(lower(${alias}.[scope])='global' OR (lower(${alias}.[scope])='branch' AND ${alias}.[scope_id]=@branch) OR (lower(${alias}.[scope])='cluster' AND EXISTS (SELECT 1 FROM dbo.[stores] scoped_store WHERE scoped_store.[id]=@branch AND COALESCE(NULLIF(scoped_store.[group_id],''),'default')=${alias}.[scope_id])) OR (lower(${alias}.[scope])='terminal' AND ${alias}.[scope_id]=@terminal))`;
}

function governanceScopePredicate(table, alias = "source") {
  if (!["authorization_actions", "authorization_action_history"].includes(table?.cloudTable))
    return null;
  return `(lower(${alias}.[scope_type])='global' OR (lower(${alias}.[scope_type])='branch' AND ${alias}.[scope_id]=@branch) OR (lower(${alias}.[scope_type])='cluster' AND EXISTS (SELECT 1 FROM dbo.[stores] scoped_store WHERE scoped_store.[id]=@branch AND COALESCE(NULLIF(scoped_store.[group_id],''),'default')=${alias}.[scope_id])))`;
}

function buildScopedWhere(
  registry,
  table,
  { historyDays = 90, alias = "source" } = {},
  predicate = branchPredicate,
) {
  const clauses = [];
  // These reserved keys are native-only lockout counters. They deliberately
  // do not upload; preserve them, but exclude them from cloud comparisons.
  if (table?.cloudTable === "pin_attempts")
    clauses.push(`${alias}.[key] NOT LIKE N'electron:%' AND ${alias}.[key] NOT LIKE N'approval-lookup:%'`);
  const explicitScope =
    settingsScopePredicate(table, alias) ?? governanceScopePredicate(table, alias);
  if (explicitScope) clauses.push(explicitScope);
  else {
    const branch = predicate(registry, table, alias);
    if (branch) clauses.push(branch);
  }
  const date = table?.retentionClass === "historical" ? dateColumn(table) : null;
  if (date && Number(historyDays) < 7300) clauses.push(`${alias}.[${date}]>=@cutoff`);
  return clauses.length ? clauses.join(" AND ") : "1=1";
}

function scopedWhere(registry, table, options) {
  return buildScopedWhere(registry, table, options);
}
function comparisonWhere(registry, table, options) {
  return buildScopedWhere(registry, table, options, comparisonBranchPredicate);
}

module.exports = {
  branchPredicate,
  comparisonWhere,
  dateColumn,
  governanceScopePredicate,
  rendererReadBranchPredicate,
  scopedWhere,
  settingsScopePredicate,
};

